//! Actual Rust candidate tests, not the Python lab or test doubles.
use vapor_core::{Config,Boundary,Emitter,Field,Obstacle,Simulation};
fn config()->Config {Config{cells:[12,16,12],cell_size:0.025,fixed_dt:0.01,pressure_iterations:96,max_velocity:3.,density_decay:0.6,boundary:Boundary::Open,..Config::default()}}
fn emitter()->Emitter{Emitter{position:[0.15,0.06,0.15],radius:0.012,length:0.03,speed:0.3,density_rate:5.,temperature:0.8,..Emitter::default()}}
#[test]fn integrated_density_budget(){let mut sim=Simulation::new_conservative_density(config()).unwrap();sim.set_emitter(0,emitter()).unwrap();let mut prior=0.;for _ in 0..60{sim.step_fixed(1).unwrap();let b=sim.density_budget().unwrap();assert!((b.before-prior).abs()<1e-12);assert!(b.injected>0.&&b.after>=0.&&b.boundary_outflow>=0.&&b.decayed>=0.&&b.saturated>=0.);assert!(b.residual.abs()<1e-9);assert!((sim.metrics().density_integral-b.after).abs()<1e-10);prior=b.after;}assert!(prior>0.);sim.remove_emitter(0).unwrap();sim.step_fixed(1).unwrap();assert_eq!(sim.density_budget().unwrap().injected,0.);assert!(sim.density_budget().unwrap().after<=prior+1e-10);}
#[test]fn reset_and_unsupported_scene(){let mut sim=Simulation::new_conservative_density(config()).unwrap();assert!(sim.set_obstacle(0,Obstacle::sphere([0.15;3],0.05)).is_err());sim.set_emitter(0,emitter()).unwrap();sim.step_fixed(3).unwrap();let mut a=vec![0.;sim.field_len(Field::Density)];sim.copy_field(Field::Density,&mut a).unwrap();sim.reset();assert!(sim.density_budget().is_none());sim.step_fixed(3).unwrap();let mut b=a.clone();sim.copy_field(Field::Density,&mut b).unwrap();assert_eq!(a,b);}
#[test]fn clipped_emitter_rejected_before_step(){let mut sim=Simulation::new_conservative_density(config()).unwrap();sim.set_emitter(0,Emitter{position:[0.,0.06,0.15],..emitter()}).unwrap();assert!(sim.step_fixed(1).is_err());assert_eq!(sim.metrics().ticks,0);assert_eq!(sim.metrics().density_integral,0.);sim.set_emitter(0,emitter()).unwrap();sim.step_fixed(1).unwrap();}
